  font-size: 0.9375rem;
  line-height: 1.75;
}

.details-inner p + p {
  margin-top: 0.75rem;
}

.details-inner ul {
  margin-top: 0.5rem;
  padding-inline-start: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

/* Footer */
.page-footer {
  text-align: center;
  margin-top: 3rem;
  color: var(--color-text-secondary);
  font-size: 0.875rem;
  padding-inline: 1rem;
}

/* Forced colors */
@media (forced-colors: active) {
  .example {
    border: 2px solid ButtonBorder;
  }

