+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --color-bg: #f8f9fb;
+  --color-surface: #ffffff;
+  --color-border: #e2e6ea;
+  --color-border-hover: #b0bec5;
+  --color-accent: #5b4fcf;
+  --color-accent-dark: #3d33a6;
+  --color-text-primary: #1a1d23;
+  --color-text-secondary: #5a6270;
+  --color-text-answer: #374151;
+  --color-focus-ring: #5b4fcf;
+  --color-header-bg: #f0eeff;
+  --radius-card: 12px;
+  --radius-btn: 8px;
+  --transition: 200ms ease;
+  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.06), 0 4px 16px rgba(0, 0, 0, 0.04);
+}
+
+body {
+  background: var(--color-bg);
+  color: var(--color-text-primary);
+  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
+  font-size: 1rem;
+  line-height: 1.6;
+  min-height: 100vh;
+  padding-block: 2rem;
+}
+
+/* Skip link */
+.skip-link {
+  position: absolute;
+  inset-inline-start: 1rem;
+  inset-block-start: 1rem;
+  padding: 0.5rem 1rem;
+  background: var(--color-accent);
+  color: #fff;
+  border-radius: var(--radius-btn);
+  font-weight: 600;
+  text-decoration: none;
+  transform: translateY(-200%);
+  z-index: 100;
+}
+
+.skip-link:focus {
+  transform: translateY(0);
+  outline: 3px solid var(--color-accent-dark);
+  outline-offset: 2px;
+}
+
+/* Page layout */
+.page-header {
+  text-align: center;
+  margin-bottom: 2.5rem;
+  padding-inline: 1rem;
+}
+
+.page-header .eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.4rem;
+  background: var(--color-header-bg);
+  color: var(--color-accent);
+  font-size: 0.8125rem;
+  font-weight: 600;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  padding: 0.3rem 0.85rem;
+  border-radius: 999px;
+  margin-bottom: 1rem;
+}
+
+.page-header h1 {
+  font-size: clamp(1.75rem, 4vw, 2.75rem);
+  font-weight: 800;
+  letter-spacing: -0.02em;
+  color: var(--color-text-primary);
+  line-height: 1.2;
+  margin-bottom: 0.75rem;
+}
+
+.page-header p {
+  font-size: 1.0625rem;
+  color: var(--color-text-secondary);
+  max-width: 44ch;
+  margin-inline: auto;
+}
+
+main {
+  max-width: 720px;
+  margin-inline: auto;
+  padding-inline: 1rem;
+}
+
+/* FAQ list */
+.faq-list {
+  display: flex;
+  flex-direction: column;
+  gap: 0.75rem;
+}
+
+/* Individual item */
+.example {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-card);
+  box-shadow: var(--shadow-card);
+  overflow: hidden;
+  transition: border-color var(--transition), box-shadow var(--transition);
+}
+
+.example:has(.faq-trigger[aria-expanded="true"]) {
+  border-color: var(--color-accent);
+  box-shadow: 0 0 0 3px rgba(91, 79, 207, 0.08), var(--shadow-card);
+}
+
+/* Trigger button */
+.faq-trigger {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  width: 100%;
+  padding: 1.1rem 1.25rem;
+  background: transparent;
+  border: none;
+  cursor: pointer;
+  text-align: start;
+  font-family: inherit;
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--color-text-primary);
+  transition: background-color var(--transition), color var(--transition);
+}
+
+.faq-trigger:hover {
+  background-color: #fafafa;
+  color: var(--color-accent);
+}
+
+.faq-trigger:focus-visible {
+  outline: 3px solid var(--color-focus-ring);
+  outline-offset: -3px;
+  border-radius: var(--radius-card);
+}
+
+.faq-trigger[aria-expanded="true"] {
+  color: var(--color-accent);
+}
+
+/* Icon */
+.faq-icon {
+  flex-shrink: 0;
+  width: 1.5rem;
+  height: 1.5rem;
+  background: var(--color-header-bg);
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  transition: background-color var(--transition), transform var(--transition);
+  color: var(--color-accent);
+}
+
+.faq-trigger[aria-expanded="true"] .faq-icon {
+  background: var(--color-accent);
+  color: #fff;
+  transform: rotate(45deg);
+}
+
+.faq-icon svg {
+  display: block;
+  fill: currentColor;
+  width: 0.75rem;
+  height: 0.75rem;
+}
+
+/* Answer panel */
+.details {
+  overflow: hidden;
+  max-height: 0;
+  transition: max-height 280ms cubic-bezier(0.4, 0, 0.2, 1);
+}
+
+.details[aria-hidden="false"] {
+  max-height: 600px;
+}
+
+.details-inner {
+  padding: 0 1.25rem 1.25rem;
+  border-top: 1px solid var(--color-border);
+  padding-top: 1rem;
+  color: var(--color-text-answer);
+  font-size: 0.9375rem;
+  line-height: 1.75;
+}
+
+.details-inner p + p {
+  margin-top: 0.75rem;
+}
+
+.details-inner ul {
+  margin-top: 0.5rem;
+  padding-inline-start: 1.5rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.35rem;
+}
+
+/* Footer */
+.page-footer {
+  text-align: center;
+  margin-top: 3rem;
+  color: var(--color-text-secondary);
+  font-size: 0.875rem;
+  padding-inline: 1rem;
+}
+
+/* Forced colors */
+@media (forced-colors: active) {
+  .example {
+    border: 2px solid ButtonBorder;
+  }
+
+  .faq-trigger {
+    color: ButtonText;
+    forced-color-adjust: none;
+  }
+
+  .faq-trigger:focus-visible {
+    outline: 3px solid Highlight;
+  }
+
+  .faq-icon {
+    forced-color-adjust: none;
+    background: ButtonFace;
+    color: ButtonText;
+    border: 1px solid ButtonBorder;
+  }
+
+  .faq-trigger[aria-expanded="true"] .faq-icon {
+    background: Highlight;
+    color: HighlightText;
+  }
+}
+
+/* Reduced motion */
+@media (prefers-reduced-motion: reduce) {
+  .details,
+  .faq-icon,
+  .example,
+  .faq-trigger {
+    transition: none;
+  }
+}
+
+/* Reflow at 320px */
+@media (max-width: 400px) {
+  .page-header h1 {
+    font-size: 1.5rem;
+  }
+
+  .faq-trigger {
+    padding: 0.9rem 1rem;
+    font-size: 0.9375rem;
+  }
+
+  .details-inner {
+    padding: 0 1rem 1rem;
+    padding-top: 0.875rem;
+  }
+}
+
')

